START TRANSACTION;
ALTER TABLE "Suppliers" ADD "CurrentVersion" integer NOT NULL DEFAULT 1;

CREATE TABLE "SupplierHistories" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "SupplierId" integer NOT NULL,
    "VersionNumber" integer NOT NULL,
    "SupplierCode" character varying(30) NOT NULL,
    "SupplierName" character varying(200) NOT NULL,
    "GSTIN" character varying(15),
    "DrugLicenseNumber" character varying(100),
    "ContactPerson" character varying(200),
    "MobileNumber" character varying(20),
    "Email" character varying(100),
    "Address" character varying(500),
    "City" character varying(100),
    "State" character varying(100),
    "Pincode" character varying(10),
    "CreditDays" integer NOT NULL,
    "CreditLimit" numeric(18,2) NOT NULL,
    "IsActive" boolean NOT NULL,
    "ChangedAt" timestamp with time zone NOT NULL,
    "ChangedBy" character varying(100) NOT NULL,
    "Reason" character varying(500),
    CONSTRAINT "PK_SupplierHistories" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SupplierHistories_Suppliers_SupplierId" FOREIGN KEY ("SupplierId") REFERENCES "Suppliers" ("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX "IX_SupplierHistories_SupplierId_VersionNumber" ON "SupplierHistories" ("SupplierId", "VersionNumber");

UPDATE "Suppliers" SET "CurrentVersion" = 1 WHERE "CurrentVersion" IS NULL OR "CurrentVersion" = 0;

